/** WKS-REG-ARCH: 96 bytes, tres vistas por tipo de registro (1 header, 3 detalle, 9 trailer). */
public sealed interface RegistroIntercambio
        permits RegistroIntercambio.Header, RegistroIntercambio.Detalle, RegistroIntercambio.Trailer {

    record Header(LocalDate fecha, String sisOrigen, String sisDestino, int tipoArchivo,
                  BigDecimal tasaFix,        // 9(08): escala no declarada en el PIC
                  BigDecimal tasaUdi,        // 9(08): escala no declarada en el PIC
                  Optional<LocalDate> fechaArt61) implements RegistroIntercambio {}

    record Detalle(int sistema,
                   String cliente,           // 9(12) como String: conserva ceros
                   String contrato,          // 9(12)
                   int producto, int instrumento, int moneda, int instOper, int numInversion,
                   LocalDate fecUltMov,      // 9(08) AAAAMMDD
                   int tipoMovto,
                   BigDecimal saldoAnterior, // S9(14)V99: ya no se usa ("Se elimina el manejo de saldos")
                   BigDecimal saldoActual,   // S9(14)V99
                   int estatusContrato,
                   boolean aplicadoLocal, boolean aplicadoForaneo) implements RegistroIntercambio {

        /** 88 WKS-CTE-ERROR VALUE 0, 999999999999. */
        public boolean clienteErroneo() {
            return cliente.chars().allMatch(c -> c == '0') || "999999999999".equals(cliente);
        }
    }

    record Trailer(long totalRegistros) implements RegistroIntercambio {}
}

/** 40000000-IDENTIFICA-HOST: la plaza deja de deducirse del nombre de la máquina. */
@ConfigurationProperties("p189.plaza")
public record Plaza(int nodoLocal, int nodoForaneo, int sistemaExterno) {

    public boolean esMonterrey() { return nodoLocal == 4; }
}

